int scif_reserve_dma_chan ( struct scif_endpt * ep ) { int err = 0 ; struct scif_dev * scifdev ; struct scif_hw_dev * sdev ; struct dma_chan * chan ; if ( ! scif_info . nodeid && scifdev_self ( ep -> remote_dev ) ) { return 0 ; } if ( scif_info . nodeid ) { scifdev = & scif_dev [ 0 ] ; } else { scifdev = ep -> remote_dev ; } sdev = scifdev -> sdev ; chan = sdev -> dma_ch [ scifdev -> dma_ch_idx ] ; scifdev -> dma_ch_idx = ( scifdev -> dma_ch_idx + 1 ) % sdev -> num_dma_ch ; mutex_lock ( & ep -> rma_info . rma_lock ) ; ep -> rma_info . dma_chan = chan ; mutex_unlock ( & ep -> rma_info . rma_lock ) ; return err ; } 